def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    strong_pressure = 0
    weak_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) < DAILY_SALARY * 1.2 or opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                weak_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    prev_bids.append(float(bid))
                    if float(bid) >= 95:
                        strong_pressure += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    slots = int(supply // WATER_REQ)
    if slots < 0:
        slots = 0

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    urgent = (hp <= 3) or (no_water_days >= 2)
    semi_urgent = (hp <= 5) or (no_water_days >= 1)
    scarce = slots <= 1
    ample = supply >= 24

    if urgent:
        bid = max(92.0, highest_prev + 3.0, DAILY_SALARY * 1.18)
        return float(min(budget, bid))

    if scarce:
        if strong_pressure >= 1:
            if semi_urgent:
                bid = max(88.0, highest_prev + 2.0)
            else:
                bid = 24.0 if weak_opponents >= 1 else 36.0
        else:
            if semi_urgent:
                bid = max(72.0, avg_prev + 4.0, 78.0)
            else:
                bid = max(28.0, avg_prev * 0.45 if avg_prev > 0 else 28.0)
    else:
        if ample:
            bid = 16.0
        else:
            if strong_pressure >= 2:
                bid = 22.0
            elif highest_prev >= 110:
                bid = 18.0
            else:
                bid = 26.0 if semi_urgent else 17.0

    if day >= 8 and hp >= 6 and budget < 140:
        bid = min(bid, 18.0)

    if weak_opponents >= 2 and not semi_urgent:
        bid = min(bid, 15.0 if not scarce else 22.0)

    min_survival = 0.0
    if no_water_days >= 1:
        min_survival = 20.0
    if semi_urgent and bid < min_survival:
        bid = min_survival

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return max(1.0, min(my_budget, DAILY_SALARY * 0.2))

    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        base_bid = max(base_bid, highest_prev_bid + 5) 

    if my_hp <= 2: 
        bid_multiplier = 1.6
        base_bid = max(base_bid, DAILY_SALARY * bid_multiplier)
    elif my_hp <= 4: 
        bid_multiplier = 1.3
        base_bid = max(base_bid, DAILY_SALARY * bid_multiplier)
    else: 
        if supply <= 18: 
            base_bid = max(base_bid, DAILY_SALARY * 1.1)
        elif supply >= 22: 
            base_bid = max(DAILY_SALARY * 0.8, base_bid * 0.9)

    days_left = EPISODE_DAYS - current_day
    if days_left <= 2 and my_hp < 5: 
        base_bid = max(base_bid, DAILY_SALARY * 1.8)
    elif days_left <= 2 and my_hp >= 5: 
        base_bid = max(base_bid, DAILY_SALARY * 1.1)

    final_bid = min(my_budget, base_bid)
    return max(1.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for k, o in opponents_status.items():
        try:
            if o.get('alive'):
                alive_opponents.append((k, o))
        except Exception:
            continue

    # If no one is alive, conserve.
    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only.
    yesterday_bids = []
    for _, o in alive_opponents:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # Estimate how many water units are likely available.
    # In this game, each unit corresponds to WATER_REQ water.
    # Use supply to infer competition pressure.
    units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0
    if units < 1:
        units = 1

    # Pressure heuristic: tighter supply => higher chance others also need water.
    # supply in [15,25] => units in [2,3].
    pressure = 0.35
    if supply <= (MIN_SUPPLY + 0.5):
        pressure = 0.75
    elif supply <= (MIN_SUPPLY + 5.0):
        pressure = 0.6
    elif supply >= (MAX_SUPPLY - 1.0):
        pressure = 0.45

    # React to yesterday's highest bids: survivors bid much higher.
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # If we are in danger, bid more aggressively.
    danger = 0.0
    if hp <= 2.0:
        danger = 1.0
    elif hp <= 3.5:
        danger = 0.7
    if no_water_days >= 1:
        danger = max(danger, 0.8)

    # Base bid level.
    # Use a target around 0.55-0.85 of DAILY_SALARY depending on pressure and danger.
    base = DAILY_SALARY * (0.55 + 0.25 * pressure + 0.2 * danger)

    # If others previously bid very high, we need to keep up.
    # Alex/Cindy had ~100+ average bids; Bob/Eric died with lower bids.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base = max(base, highest_prev_bid * 0.9)
    elif highest_prev_bid >= DAILY_SALARY * 0.65:
        base = max(base, highest_prev_bid * 0.7)

    # If we have low budget, scale down but still respond to danger.
    if budget <= DAILY_SALARY * 0.6:
        base = min(base, budget * (0.85 if danger > 0.6 else 0.6))

    # Add small day-dependent tie-breaker to avoid identical bids.
    # Keep deterministic and bounded.
    tie = ((day % 5) - 2) * 1.5

    bid = base + tie

    # Ensure bid is within feasible bounds.
    if bid < 0.0:
        bid = 0.0
    if budget < bid:
        bid = budget

    # Never bid above a reasonable fraction of budget to avoid elimination.
    cap = budget if budget <= DAILY_SALARY else min(budget, DAILY_SALARY * 1.2)
    if bid > cap:
        bid = cap

    return float(bid)
